import { state } from './state.js';
import { notifyNewOrder } from './order-alert.js';

const app = { view: 'dashboard', data: {}, selectedFolio: null, selectedStay: null };
const content = document.getElementById('pms-content');
const title = document.getElementById('pms-title');
const banner = document.getElementById('pms-banner');
const names = { dashboard: 'Günlük Durum', rack: 'Oda Planı', reservations: 'Rezervasyonlar', precheckins: 'Online Ön Girişler', checkin: 'Giriş İşlemleri', stays: 'Konaklayanlar', folios: 'Folyo ve Tahsilat', invoices: 'Faturalar', tasks: 'Görevler', kbs: 'KBS Bildirimleri', shifts: 'Vardiya ve Kasa', reports: 'Raporlar', channels: 'HotelRunner Kanal Yönetimi' };
const escapeHtml = value => String(value ?? '').replace(/[&<>'"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[char]));
const money = value => new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(Number(value || 0));
const labels = { inquiry: 'Bilgi Talebi', option: 'Opsiyon', confirmed: 'Onaylandı', guaranteed: 'Garantili', pending: 'Bekliyor', paid: 'Ödendi', partial: 'Kısmi Ödeme', local: 'Yerel', synced: 'Senkronize', issued: 'Kesildi', credit_card: 'Kredi Kartı', cash: 'Nakit', bank_transfer: 'Banka Havalesi', online_link: 'Ödeme Bağlantısı', agency: 'Acenta', company_receivable: 'Şirket Cari Hesabı', not_started: 'Başlamadı', submitted: 'Gönderildi', reviewed: 'İncelendi', converted: 'Rezervasyon Oluşturuldu', accepted: 'Kabul Edildi', manual_review: 'Manuel İnceleme', clean_vacant: 'Temiz Boş', dirty_vacant: 'Kirli Boş', occupied: 'Dolu', maintenance: 'Bakımda', out_of_order: 'Kullanıma Kapalı', blocked: 'Bloke', checked_in: 'Giriş Yapıldı', checked_out: 'Çıkış Yapıldı', completed: 'Tamamlandı', cancelled: 'İptal Edildi', rejected: 'Reddedildi', open: 'Açık', working: 'Çalışıyor', off: 'Kapalı', accommodation: 'Konaklama', restaurant: 'Restoran', minibar: 'Minibar', laundry: 'Çamaşırhane', transfer: 'Transfer', charge: 'Diğer Masraf', payment: 'Tahsilat', reversal: 'İptal İşlemi', housekeeping: 'Kat Hizmetleri', maintenance_task: 'Teknik Servis', wakeup: 'Uyandırma', porter: 'Bagaj', taxi: 'Taksi', low: 'Düşük', normal: 'Normal', high: 'Yüksek', urgent: 'Acil', reception: 'Resepsiyon', technical: 'Teknik Servis', kitchen: 'Mutfak' };
const label = value => labels[String(value || '').toLowerCase()] || String(value || '-');
const today = () => new Date().toISOString().slice(0, 10);
const dateAfter = days => { const date = new Date(); date.setDate(date.getDate() + days); return date.toISOString().slice(0, 10); };
const formatTurkishDate = value => { const [year, month, day] = String(value || '').split('-'); return year && month && day ? `${day}/${month}` : String(value || '-'); };

async function api(path, options = {}) {
  const response = await fetch(`/api/reception${path}${path.includes('?') ? '&' : '?'}tenant_id=${encodeURIComponent(state.currentTenant)}`, { ...options, headers: { 'Content-Type': 'application/json', ...(options.headers || {}) } });
  if (response.status === 204) return null;
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body.error || 'İşlem tamamlanamadı.');
  return body;
}

function message(text, type = 'warning') { banner.hidden = false; banner.textContent = text; banner.className = `pms-banner ${type}`; setTimeout(() => { banner.hidden = true; }, 6000); }
function initReceptionSSE() { const stream = new EventSource(`/api/events?tenant_id=${encodeURIComponent(state.currentTenant)}`); stream.addEventListener('precheckin_submitted', event => { const item = JSON.parse(event.data || '{}'); message(`${item.guestName || 'Misafir'} QR ön giriş formunu gönderdi.`, 'success'); if (app.view === 'checkin' || app.view === 'precheckins') showView(app.view); }); stream.addEventListener('room_updated', () => { if (['dashboard', 'rack', 'stays', 'checkin'].includes(app.view)) showView(app.view); }); stream.addEventListener('request_updated', () => { if (app.view === 'folios') showView('folios'); }); stream.addEventListener('request_created', event => { let departments = []; try { departments = JSON.parse(event.data || '{}').departments || []; } catch (error) { departments = []; } if (departments.some(department => String(department).toLocaleLowerCase('tr-TR') === 'reception')) notifyNewOrder(event); if (app.view === 'tasks') showView('tasks'); }); stream.onerror = () => { stream.close(); setTimeout(initReceptionSSE, 3000); }; }
function badge(status) { const className = ['checked_in', 'checked_out', 'confirmed', 'accepted', 'completed', 'open', 'paid', 'reviewed'].includes(status) ? 'success' : ['cancelled', 'rejected', 'maintenance', 'dirty_vacant'].includes(status) ? 'danger' : ''; return `<span class="pms-badge ${className}">${escapeHtml(label(status))}</span>`; }
function table(headers, rows) { return `<div class="pms-table-wrap"><table class="pms-table"><thead><tr>${headers.map(item => `<th>${item}</th>`).join('')}</tr></thead><tbody>${rows || ''}</tbody></table></div>`; }
function openModal(modalTitle, body) { document.getElementById('pms-modal-title').textContent = modalTitle; document.getElementById('pms-modal-body').innerHTML = body; document.getElementById('pms-modal').hidden = false; }
function closeModal() { document.getElementById('pms-modal').hidden = true; }
function formData(form) { return Object.fromEntries(new FormData(form).entries()); }
function formLayout(fields, submitLabel) { return `<form class="pms-form" data-form>${fields.join('')}<div class="wide pms-actions"><button class="btn btn-primary" type="submit">${submitLabel}</button><button class="btn btn-secondary" type="button" data-close>Vazgeç</button></div></form>`; }
function field(label, name, type = 'text', value = '', options = null, wide = false) { if (options) return `<label class="${wide ? 'wide' : ''}">${label}<select name="${name}">${options.map(option => `<option value="${escapeHtml(option.value || option)}" ${String(option.value || option) === String(value) ? 'selected' : ''}>${escapeHtml(option.label || option)}</option>`).join('')}</select></label>`; if (type === 'textarea') return `<label class="${wide ? 'wide' : ''}">${label}<textarea name="${name}">${escapeHtml(value)}</textarea></label>`; return `<label class="${wide ? 'wide' : ''}">${label}<input name="${name}" type="${type}" value="${escapeHtml(value)}"></label>`; }

async function renderDashboard() {
  const data = await api(`/dashboard?date=${today()}`); app.data.dashboard = data;
  const financialMetrics = new Set(['outstanding_balance', 'total_accrual', 'total_collection', 'daily_accrual', 'daily_collection', 'daily_revenue']);
  const items = [['arrivals', 'Bugünkü Girişler'], ['departures', 'Beklenen Çıkışlar'], ['in_house', 'Konaklayanlar'], ['occupancy', 'Doluluk %'], ['clean_available', 'Temiz Boş'], ['dirty_vacant', 'Kirli Boş'], ['maintenance', 'Bakımda'], ['unassigned', 'Atamasız Rezervasyon'], ['total_accrual', 'Toplam Tahakkuk'], ['total_collection', 'Toplam Tahsilat'], ['outstanding_balance', 'Açık Bakiye'], ['daily_revenue', 'Bugünkü Ciro'], ['daily_collection', 'Folyo Tahsilatı'], ['payment_attention', 'Ödeme Hatırlatması'], ['identity_attention', 'KBS Bekleyen'], ['channel_attention', 'Kanal Uyarısı'], ['open_tasks', 'Açık Görev'], ['vip', 'VIP Oda']];
  content.innerHTML = `<div class="pms-grid">${items.map(([key, label]) => `<article class="pms-kpi" data-go="${key}"><strong>${financialMetrics.has(key) ? money(data.metrics[key]) : data.metrics[key]}</strong><span>${label}</span></article>`).join('')}</div><article class="pms-card"><h2>Operasyon Öncelikleri</h2><div class="pms-list"><div class="pms-list-item"><span>Geç varış, no-show ve geç çıkış adayları</span><strong>${data.metrics.late_arrivals + data.metrics.no_show_candidates + data.metrics.late_checkouts}</strong></div><div class="pms-list-item"><span>Kimlik bildirimi ve departman bekleyenleri</span><strong>${data.metrics.identity_attention + data.metrics.open_tasks}</strong></div></div></article>`;
  content.querySelectorAll('[data-go]').forEach(button => button.addEventListener('click', () => { if (button.dataset.go === 'channel_attention') showView('channels'); else if (['arrivals', 'unassigned', 'payment_attention'].includes(button.dataset.go)) showView('reservations'); else if (button.dataset.go === 'identity_attention') showView('kbs'); else if (button.dataset.go === 'open_tasks') showView('tasks'); else if (financialMetrics.has(button.dataset.go)) showView('folios'); else showView('rack'); }));
}

async function renderRack() {
  const [rack, stays] = await Promise.all([api(`/room-rack?from=${today()}&days=14`), api('/stays')]); app.data.rack = rack; app.data.stays = stays;
  const dates = Array.from({ length: 14 }, (_, index) => { const value = new Date(`${rack.from}T00:00:00Z`); value.setUTCDate(value.getUTCDate() + index); return value.toISOString().slice(0, 10); });
  const grid = [`<div class="pms-rack-head">Oda</div>${dates.map(day => `<div class="pms-rack-head">${formatTurkishDate(day)}</div>`).join('')}`];
  rack.rooms.forEach(room => { grid.push(`<div class="pms-rack-room">${escapeHtml(room.room_number)}<div class="pms-muted">${escapeHtml(label(room.status))}</div></div>`); dates.forEach(day => { const assignment = rack.assignments.find(item => item.room_id === room.id && item.start_date <= day && item.end_date > day); const block = rack.blocks.find(item => item.room_id === room.id && item.start_date <= day && item.end_date > day); const status = block ? 'maintenance' : assignment ? 'occupied' : ''; grid.push(`<div class="pms-rack-day ${status}" data-room="${room.id}" data-date="${day}">${assignment ? `<button class="pms-rack-block" data-reservation="${assignment.reservation_id}">${escapeHtml(assignment.guest_name || assignment.reservation_number)}</button>` : block ? `<span class="pms-badge danger">${escapeHtml(block.block_type)}</span>` : ''}</div>`); }); });
  content.innerHTML = `<div class="pms-section-tools"><div><strong>${formatTurkishDate(rack.from)} — ${formatTurkishDate(rack.to)}</strong></div><div class="pms-actions"><button id="rack-room" class="btn btn-secondary">Oda Tanımla</button><button id="rack-new" class="btn btn-primary">Boş Hücreden Rezervasyon</button></div></div>${rack.rooms.length ? `<div class="pms-rack"><div class="pms-rack-grid" style="grid-template-columns:180px repeat(14,minmax(72px,1fr))">${grid.join('')}</div></div>` : '<div class="pms-empty">Henüz fiziksel oda tanımlanmadı. Yönetici olarak oda envanterini ekleyin.</div>'}`;
  content.querySelectorAll('[data-reservation]').forEach(button => button.addEventListener('click', event => { event.stopPropagation(); const stay = stays.find(item => item.reservation_id === button.dataset.reservation); if (stay) openRoomCenter(rack.rooms.find(room => room.id === stay.room_id), stay, []); else openReservation(button.dataset.reservation); }));
  content.querySelectorAll('.pms-rack-day[data-room]').forEach(cell => cell.addEventListener('click', () => openReservationForm({ room_id: cell.dataset.room, arrival_date: cell.dataset.date, departure_date: dateAfter(1) })));
  document.getElementById('rack-new').addEventListener('click', () => openReservationForm({}));
  document.getElementById('rack-room').addEventListener('click', openRoomForm);
}

function openRoomForm() { openModal('Fiziksel Oda Tanımı', formLayout([field('Oda Numarası', 'room_number'), field('Oda Tipi', 'room_type', 'text', 'standard'), field('Kat', 'floor', 'number', 1), field('Yatak Tipi', 'bed_type', 'text', 'double'), field('Kapasite', 'capacity', 'number', 2), field('Baz Fiyat', 'base_rate', 'number', 0)], 'Odayı Kaydet')); const form = document.querySelector('[data-form]'); form.addEventListener('submit', async event => { event.preventDefault(); const data = formData(form); ['floor', 'capacity', 'base_rate'].forEach(key => data[key] = Number(data[key])); try { await api('/rooms', { method: 'POST', body: JSON.stringify(data) }); closeModal(); message('Fiziksel oda tanımlandı.', 'success'); showView('rack'); } catch (error) { message(error.message); } }); document.querySelector('[data-close]').addEventListener('click', closeModal); }

async function renderReservations(search = '') {
  const rows = await api(`/reservations?search=${encodeURIComponent(search)}`); app.data.reservations = rows;
  content.innerHTML = `<div class="pms-section-tools"><input id="reservation-search" placeholder="Rezervasyon, misafir, voucher, kanal, oda" value="${escapeHtml(search)}"><button id="reservation-create" class="btn btn-primary"><i class="fa-solid fa-plus"></i> Yeni Rezervasyon</button></div>${table(['No', 'Kaynak', 'Misafir', 'Varış', 'Ayrılış', 'Oda', 'Durum', 'Senkron', 'Toplam'], rows.map(row => `<tr data-reservation="${row.id}"><td>${escapeHtml(row.reservation_number)}</td><td>${escapeHtml(row.agency || row.booking_source || 'Doğrudan')}<div class="pms-muted">${escapeHtml(row.voucher_number || row.external_reservation_id || '')}</div></td><td>${escapeHtml(`${row.first_name || ''} ${row.last_name || ''}`)}</td><td>${row.arrival_date}</td><td>${row.departure_date}</td><td>${escapeHtml(row.room_number || row.room_type || 'Atanmadı')}</td><td>${badge(row.status)}</td><td>${badge(row.channel_sync_status || (row.external_provider ? 'synced' : 'local'))}</td><td>${money(row.total_amount)}</td></tr>`).join(''))}`;
  document.getElementById('reservation-create').addEventListener('click', () => openReservationForm({}));
  document.getElementById('reservation-search').addEventListener('change', event => renderReservations(event.target.value));
  content.querySelectorAll('[data-reservation]').forEach(row => row.addEventListener('click', () => openReservation(row.dataset.reservation)));
}

async function renderPrecheckins() {
  const submissions = await api('/precheckins');
  content.innerHTML = `<div class="pms-section-tools"><div><strong>Sabit Misafir Ön Giriş Formu</strong><div class="pms-muted">Misafir kişisel bilgilerini gönderir; rezervasyon, oda, tarih, fiyat ve ödeme ayrıntılarını resepsiyon tamamlar.</div></div><button id="show-precheckin-qr" class="btn btn-primary">Sabit QR'ı Göster</button></div>${table(['Gönderim', 'Misafir', 'Telefon', 'Kimlik / Pasaport', 'Özel İstek', 'Durum', 'İşlem'], submissions.map(item => `<tr><td>${String(item.submitted_at || '').replace('T', ' ').slice(0, 16)}</td><td>${escapeHtml(`${item.payload.first_name || ''} ${item.payload.last_name || ''}`)}</td><td>${escapeHtml(item.payload.phone || '-')}</td><td>${escapeHtml(item.payload.identity_number || item.payload.passport_number || '-')}</td><td>${escapeHtml(item.payload.special_requests || '-')}</td><td>${badge(item.status)}</td><td>${item.status === 'submitted' ? `<div class="pms-actions"><button class="btn btn-primary" data-precheckin-approve="${item.id}">Onayla ve Rezervasyon Hazırla</button><button class="btn btn-danger" data-precheckin-delete="${item.id}">Sil</button></div>` : item.status === 'reviewed' ? `<div class="pms-actions"><button class="btn btn-secondary" data-precheckin-resume="${item.id}">Rezervasyonu Hazırla</button><button class="btn btn-danger" data-precheckin-delete="${item.id}">Sil</button></div>` : escapeHtml(item.reservation_number || 'Tamamlandı')}</td></tr>`).join('') || '<tr><td colspan="7" class="pms-muted">Henüz misafir formu gönderilmedi.</td></tr>')}`;
  document.getElementById('show-precheckin-qr').addEventListener('click', openPrecheckinQr);
  content.querySelectorAll('[data-precheckin-approve]').forEach(button => button.addEventListener('click', async () => { try { const result = await api(`/precheckins/${button.dataset.precheckinApprove}/approve`, { method: 'POST', body: '{}' }); closeModal(); message('Misafir bilgileri alındı. Rezervasyon ayrıntılarını resepsiyon olarak tamamlayın.', 'success'); openReservationForm({ ...result.payload, precheckin_submission_id: button.dataset.precheckinApprove, status: 'confirmed', booking_source: 'online_precheckin' }); } catch (error) { message(error.message); } }));
  content.querySelectorAll('[data-precheckin-resume]').forEach(button => button.addEventListener('click', () => { const item = submissions.find(entry => entry.id === button.dataset.precheckinResume); if (item) openReservationForm({ ...item.payload, precheckin_submission_id: item.id, status: 'confirmed', booking_source: 'online_precheckin' }); }));
  content.querySelectorAll('[data-precheckin-delete]').forEach(button => button.addEventListener('click', async () => { if (!window.confirm('Bu ön giriş kaydı silinsin mi?')) return; try { await api(`/precheckins/${button.dataset.precheckinDelete}`, { method: 'DELETE' }); message('Ön giriş kaydı silindi.', 'success'); showView('precheckins'); } catch (error) { message(error.message); } }));
}

async function openReservation(reservationId) {
  const reservation = app.data.reservations?.find(item => item.id === reservationId) || (await api('/reservations')).find(item => item.id === reservationId);
  if (!reservation) return message('Rezervasyon bulunamadı.');
  const deposit = Number(reservation.deposit_amount || 0); const remaining = Math.max(0, Number(reservation.total_amount || 0) - deposit);
  openModal(`Rezervasyon ${reservation.reservation_number}`, `<div class="pms-list"><div class="pms-list-item"><span>Misafir</span><strong>${escapeHtml(`${reservation.first_name || ''} ${reservation.last_name || ''}`)}</strong></div><div class="pms-list-item"><span>Kaynak / Rezervasyon Kodu</span><strong>${escapeHtml(reservation.agency || reservation.booking_source || 'Doğrudan')} · ${escapeHtml(reservation.voucher_number || reservation.external_reservation_id || '-')}</strong></div><div class="pms-list-item"><span>Kanal Senkronu</span><strong>${badge(reservation.channel_sync_status || (reservation.external_provider ? 'synced' : 'local'))}</strong></div><div class="pms-list-item"><span>Tarih</span><strong>${reservation.arrival_date} — ${reservation.departure_date}</strong></div><div class="pms-list-item"><span>Oda / Durum</span><strong>${escapeHtml(reservation.room_number || reservation.room_type || 'Atanmadı')} ${badge(reservation.status)}</strong></div><div class="pms-list-item"><span>Ödeme Planı</span><strong>${escapeHtml(label(reservation.payment_method || 'credit_card'))} · ${badge(reservation.payment_status || 'pending')}</strong></div><div class="pms-list-item"><span>Kapora</span><strong>${money(deposit)}</strong></div><div class="pms-list-item"><span>Kalan Ödeme</span><strong>${money(remaining)}</strong></div><div class="pms-list-item"><span>Ödeme Hatırlatması</span><strong>${escapeHtml(reservation.payment_due_date || '-')} ${escapeHtml(reservation.payment_reminder || '')}</strong></div><div class="pms-list-item"><span>Toplam</span><strong>${money(reservation.total_amount)}</strong></div></div><div class="pms-actions"><button class="btn btn-primary" id="reservation-edit">Düzenle</button><button class="btn btn-success" id="reservation-checkin">Giriş İşlemini Başlat</button></div>`);
  document.getElementById('reservation-edit').addEventListener('click', () => openReservationForm(reservation));
  document.getElementById('reservation-checkin').addEventListener('click', () => openCheckin(reservation));
}

function openPrecheckinQr() { const url = `${window.location.origin}/precheckin.html?tenant_id=${encodeURIComponent(state.currentTenant)}`; const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=240x240&margin=2&data=${encodeURIComponent(url)}`; openModal('Sabit Misafir Online Ön Giriş QR', `<div class="precheckin-qr"><img src="${escapeHtml(qrUrl)}" alt="Misafir ön giriş QR kodu" width="240" height="240"><p>Bu tek QR kodunu tüm misafirlerle paylaşın. Misafir yalnızca kişisel bilgilerini gönderir; oda, tarih, fiyat ve ödeme bilgilerini resepsiyon tamamlar.</p><a href="${escapeHtml(url)}" target="_blank" rel="noopener">${escapeHtml(url)}</a><div class="pms-actions"><button id="copy-precheckin" class="btn btn-primary">Bağlantıyı Kopyala</button></div></div>`); document.getElementById('copy-precheckin').addEventListener('click', async () => { await navigator.clipboard.writeText(url); message('Sabit ön giriş bağlantısı kopyalandı.', 'success'); }); }

async function openReservationForm(value) {
  const rooms = await api(`/availability?arrival_date=${value.arrival_date || today()}&departure_date=${value.departure_date || dateAfter(1)}${value.id ? `&exclude_reservation_id=${encodeURIComponent(value.id)}` : ''}`).catch(() => ({ rooms: [] }));
  const statuses = ['inquiry', 'option', 'confirmed', 'guaranteed'];
  const roomOptions = [{ value: '', label: 'Oda atamasız' }, ...rooms.rooms.map(room => ({ value: room.id, label: room.room_number }))];
  openModal(value.id ? 'Rezervasyon Düzenle' : 'Yeni Rezervasyon', formLayout([
    field('Ad', 'first_name', 'text', value.first_name || ''), field('Soyad', 'last_name', 'text', value.last_name || ''), field('Telefon', 'phone', 'tel', value.phone || ''), field('E-posta', 'email', 'email', value.contact_email || value.email || ''), field('Uyruk', 'nationality', 'text', value.nationality || 'TR'), field('T.C. Kimlik / Pasaport', 'identity_number', 'text', value.identity_number || value.passport_number || ''), field('Varış', 'arrival_date', 'date', value.arrival_date || today()), field('Ayrılış', 'departure_date', 'date', value.departure_date || dateAfter(1)), field('Oda', 'room_id', 'text', value.room_id || '', roomOptions), field('Durum', 'status', 'text', value.status || 'inquiry', statuses), field('Pansiyon', 'board_type', 'text', value.board_type || 'BB', ['BB', 'HB', 'FB', 'AI', 'RO']), field('Gecelik Fiyat', 'nightly_rate', 'number', value.nightly_rate || 0), field('Yetişkin', 'adults', 'number', value.adults || 1), field('Çocuk', 'children', 'number', value.children || 0), field('Ödeme Yöntemi', 'payment_method', 'text', value.payment_method || 'credit_card', [{ value: 'cash', label: 'Nakit' }, { value: 'credit_card', label: 'Kredi Kartı' }, { value: 'bank_transfer', label: 'Banka Havalesi' }, { value: 'online_link', label: 'Ödeme Linki' }, { value: 'agency', label: 'Acenta' }, { value: 'company_receivable', label: 'Şirket Cari Hesabı' }]), field('Ödeme Durumu', 'payment_status', 'text', value.payment_status || 'pending', [{ value: 'pending', label: 'Bekliyor' }, { value: 'partial', label: 'Kısmi Ödeme' }, { value: 'paid', label: 'Ödendi' }, { value: 'agency', label: 'Acenta Tahsilatı' }]), field('Kapora', 'deposit_amount', 'number', value.deposit_amount || 0), field('Son Ödeme Tarihi', 'payment_due_date', 'date', value.payment_due_date || value.arrival_date || today()), field('Ödeme Hatırlatması', 'payment_reminder', 'textarea', value.payment_reminder || '', null, true), field('Rezervasyon Kaynağı', 'booking_source', 'text', value.booking_source || ''), field('Misafir Özel İstekleri', 'special_requests', 'textarea', value.special_requests || '', null, true), field('İç Not', 'internal_notes', 'textarea', value.internal_notes || '', null, true)
  ], value.id ? 'Kaydet' : 'Rezervasyonu Oluştur'));
  const form = document.querySelector('[data-form]'); const roomRates = new Map(rooms.rooms.map(room => [room.id, Number(room.base_rate || 0)])); const applyRoomRate = () => { const rate = roomRates.get(form.elements.room_id.value); if (Number.isFinite(rate) && rate >= 0) form.elements.nightly_rate.value = rate.toFixed(2); }; form.elements.room_id.addEventListener('change', applyRoomRate); if (!Number(value.nightly_rate || 0) && form.elements.room_id.value) applyRoomRate(); form.addEventListener('submit', async event => { event.preventDefault(); const data = formData(form); if (value.precheckin_submission_id) data.precheckin_submission_id = value.precheckin_submission_id; data.adults = Number(data.adults); data.children = Number(data.children); data.nightly_rate = Number(data.nightly_rate); data.deposit_amount = Number(data.deposit_amount); data.main_guest = { first_name: data.first_name, last_name: data.last_name, phone: data.phone, email: data.email, nationality: data.nationality, identity_number: data.identity_number, document_type: data.nationality === 'TR' ? 'national_id' : 'passport' }; try { if (value.id) await api(`/reservations/${value.id}`, { method: 'PATCH', body: JSON.stringify(data) }); else await api('/reservations', { method: 'POST', body: JSON.stringify(data) }); closeModal(); message('Rezervasyon ve ödeme planı kaydedildi.', 'success'); showView(value.id ? 'reservations' : 'checkin'); } catch (error) { message(error.message); } });
  document.querySelector('[data-close]').addEventListener('click', closeModal);
}

async function openCheckin(reservation) {
  const selected = reservation || app.data.reservations?.find(item => ['confirmed', 'guaranteed', 'option', 'inquiry'].includes(item.status));
  if (!selected) return message('Giriş işlemi için uygun rezervasyon bulunamadı.');
  const identityRequired = String(selected.nationality || 'TR').toUpperCase() === 'TR' ? 'T.C. Kimlik No (11 hane)' : 'Pasaport No';
  openModal('Giriş Hazırlığı', `<p class="pms-muted">Girişten önce kimlik bilgilerini tamamlayın. T.C. vatandaşları için 11 haneli T.C. Kimlik No, diğer uyruklar için pasaport numarası zorunludur.</p>${formLayout([field('Ad', 'first_name', 'text', selected.first_name || ''), field('Soyad', 'last_name', 'text', selected.last_name || ''), field('Uyruk', 'nationality', 'text', selected.nationality || 'TR', [{ value: 'TR', label: 'Türkiye' }, { value: 'OTHER', label: 'Diğer' }]), field(identityRequired, 'identity_number', 'text', selected.identity_number || ''), field('Pasaport No', 'passport_number', 'text', selected.passport_number || ''), field('Telefon', 'phone', 'tel', selected.phone || ''), field('E-posta', 'email', 'email', selected.contact_email || selected.email || '')], 'Kimlik Bilgilerini Kaydet ve Giriş Yap')}`);
  const form = document.querySelector('[data-form]');
  form.addEventListener('submit', async event => {
    event.preventDefault();
    const data = formData(form);
    data.main_guest = { first_name: data.first_name, last_name: data.last_name, nationality: data.nationality, identity_number: data.identity_number, passport_number: data.passport_number, phone: data.phone, email: data.email, document_type: data.nationality === 'TR' ? 'national_id' : 'passport' };
    try {
      await api(`/reservations/${selected.id}`, { method: 'PATCH', body: JSON.stringify(data) });
      const result = await api('/checkin', { method: 'POST', body: JSON.stringify({ reservation_id: selected.id }) });
      closeModal();
      message(`Giriş işlemi tamamlandı. Folyo: ${result.folio_id}`, 'success');
      app.selectedFolio = result.folio_id;
      showView('stays');
    } catch (error) { message(error.message); }
  });
  document.querySelector('[data-close]').addEventListener('click', closeModal);
}

async function renderCheckin() {
  const [allReservations, submissions, reservationPrecheckins] = await Promise.all([api('/reservations'), api('/precheckins'), api('/reservation-precheckins')]);
  const reservations = allReservations.filter(row => ['inquiry', 'option', 'confirmed', 'guaranteed'].includes(row.status));
  const pendingSubmissions = submissions.filter(item => ['submitted', 'reviewed'].includes(item.status));
  app.data.reservations = allReservations;
  const submissionRows = pendingSubmissions.map(item => {
    const action = item.status === 'submitted' ? 'Onayla ve Rezervasyon Hazırla' : 'Rezervasyonu Hazırla';
    return `<tr><td>${String(item.submitted_at || '').replace('T', ' ').slice(0, 16)}</td><td>${escapeHtml(`${item.payload.first_name || ''} ${item.payload.last_name || ''}`)}</td><td>${escapeHtml(item.payload.phone || '-')}</td><td>${escapeHtml(item.payload.identity_number || item.payload.passport_number || '-')}</td><td>Yeni kayıt</td><td>${escapeHtml(item.payload.special_requests || '')}</td><td>${badge(item.status)}</td><td><div class="pms-actions"><button class="btn btn-primary" data-precheckin-approve="${item.id}">${action}</button><button class="btn btn-danger" data-precheckin-delete="${item.id}">Sil</button></div></td></tr>`;
  }).concat(reservationPrecheckins.map(item => `<tr><td>${String(item.submitted_at || '').replace('T', ' ').slice(0, 16)}</td><td>${escapeHtml(`${item.payload.first_name || ''} ${item.payload.last_name || ''}`)}</td><td>${escapeHtml(item.payload.phone || '-')}</td><td>${escapeHtml(item.payload.identity_number || item.payload.passport_number || '-')}</td><td>${escapeHtml(item.reservation_number || '-')}</td><td>${escapeHtml(item.payload.special_requests || '')}</td><td>${badge(item.status)}</td><td>${item.status === 'submitted' ? `<button class="btn btn-primary" data-reservation-precheckin-review="${item.reservation_id}">Rezervasyona Aktar</button>` : 'Aktarıldı'}</td></tr>`)).join('') || '<tr><td colspan="8" class="pms-muted">Bekleyen QR formu yok.</td></tr>';
  const reservationRows = reservations.map(row => { const identityComplete = String(row.nationality || 'TR').toUpperCase() === 'TR' ? /^\d{11}$/.test(String(row.identity_number || '')) : String(row.passport_number || '').trim().length >= 4; return `<tr><td>${escapeHtml(row.reservation_number)}</td><td>${escapeHtml(row.booking_source || 'Doğrudan')}</td><td>${escapeHtml(`${row.first_name || ''} ${row.last_name || ''}`)}</td><td>${escapeHtml(row.room_number || 'Atanmadı')}</td><td>${row.arrival_date}</td><td>${identityComplete ? 'Tamam' : 'Eksik'}</td><td>${badge(row.status)}</td><td><div class="pms-actions"><button class="btn btn-secondary" data-checkin-edit="${row.id}">Düzenle</button>${identityComplete ? '' : `<button class="btn btn-secondary" data-precheckin-link="${row.id}">Ön Giriş Linki Gönder</button>`}<button class="btn btn-success" data-checkin="${row.id}">${identityComplete ? 'Giriş Yap' : 'Kimlik Bilgisi Gir'}</button></div></td></tr>`; }).join('') || '<tr><td colspan="8" class="pms-muted">Girişe hazır rezervasyon yok.</td></tr>';
  content.innerHTML = `<div class="pms-section-tools"><div><strong>Giriş Merkezi</strong><div class="pms-muted">Manuel rezervasyonlar ve QR ile gelen misafir bilgileri aynı giriş akışında yönetilir.</div></div><button id="show-precheckin-qr" class="btn btn-primary">Sabit QR'ı Göster</button></div><article class="pms-card"><h2>QR Formundan Gelen Misafir Bilgileri</h2><p class="pms-muted">Fiziksel QR kartını tarayan misafirlerin bilgileri buraya düşer. Rezervasyon bağlantısıyla gelen formu doğrudan ilgili rezervasyona aktarın.</p>${table(['Gönderim', 'Misafir', 'Telefon', 'Kimlik / Pasaport', 'Rezervasyon', 'Özel İstek', 'Durum', 'İşlem'], submissionRows)}</article><article class="pms-card"><h2>Girişe Hazır Rezervasyonlar</h2><p class="pms-muted">Manuel eklenen ve QR formundan hazırlanan tüm açık rezervasyonlar burada görünür.</p>${table(['Rezervasyon', 'Kaynak', 'Misafir', 'Oda', 'Varış', 'Kimlik', 'Durum', 'İşlem'], reservationRows)}</article>`;
  document.getElementById('show-precheckin-qr').addEventListener('click', openPrecheckinQr);
  content.querySelectorAll('[data-precheckin-approve]').forEach(button => button.addEventListener('click', async () => {
    const item = pendingSubmissions.find(entry => entry.id === button.dataset.precheckinApprove);
    if (!item) return;
    try {
      const result = item.status === 'submitted' ? await api(`/precheckins/${item.id}/approve`, { method: 'POST', body: '{}' }) : { payload: item.payload };
      openReservationForm({ ...result.payload, precheckin_submission_id: item.id, status: 'confirmed', booking_source: 'online_precheckin' });
    } catch (error) { message(error.message); }
  }));
  content.querySelectorAll('[data-precheckin-delete]').forEach(button => button.addEventListener('click', async () => {
    if (!window.confirm('Bu QR form kaydı silinsin mi?')) return;
    try {
      await api(`/precheckins/${button.dataset.precheckinDelete}`, { method: 'DELETE' });
      message('QR form kaydı silindi.', 'success');
      showView('checkin');
    } catch (error) { message(error.message); }
  }));
  content.querySelectorAll('[data-reservation-precheckin-review]').forEach(button => button.addEventListener('click', async () => {
    try {
      await api(`/reservations/${button.dataset.reservationPrecheckinReview}/precheckin/review`, { method: 'POST', body: '{}' });
      message('QR form bilgileri rezervasyona aktarıldı.', 'success');
      showView('checkin');
    } catch (error) { message(error.message); }
  }));
  content.querySelectorAll('[data-checkin-edit]').forEach(button => button.addEventListener('click', () => openReservationForm(reservations.find(row => row.id === button.dataset.checkinEdit))));
  content.querySelectorAll('[data-checkin]').forEach(button => button.addEventListener('click', () => openCheckin(reservations.find(row => row.id === button.dataset.checkin))));
  content.querySelectorAll('[data-precheckin-link]').forEach(button => button.addEventListener('click', () => openReservationPrecheckinLink(button.dataset.precheckinLink)));
}

async function openReservationPrecheckinLink(reservationId) {
  openModal('Rezervasyona Özel Online Ön Giriş Linki', '<div class="pms-empty">Bağlantı hazırlanıyor…</div>');
  try {
    const result = await api(`/reservations/${reservationId}/precheckin`);
    const url = `${window.location.origin}${result.url}`;
    document.getElementById('pms-modal-body').innerHTML = `<div class="precheckin-qr"><p>Bu bağlantı yalnızca <strong>${escapeHtml(result.reservation_number)}</strong> numaralı rezervasyona bağlıdır. Misafire WhatsApp/SMS ile gönderin; doldurduğunda kimlik bilgileri doğrudan bu rezervasyona işlenir.</p><a href="${escapeHtml(url)}" target="_blank" rel="noopener">${escapeHtml(url)}</a><p class="pms-muted">Geçerlilik: ${escapeHtml(String(result.expires_at || '').replace('T', ' ').slice(0, 16))} · Durum: ${escapeHtml(result.status === 'not_started' ? 'Henüz doldurulmadı' : result.status)}</p><div class="pms-actions"><button id="copy-reservation-precheckin" class="btn btn-primary">Bağlantıyı Kopyala</button></div></div>`;
    document.getElementById('copy-reservation-precheckin').addEventListener('click', async () => { await navigator.clipboard.writeText(url); message('Ön giriş bağlantısı kopyalandı.', 'success'); });
  } catch (error) {
    document.getElementById('pms-modal-body').innerHTML = `<div class="pms-empty pms-danger">${escapeHtml(error.message)}</div>`;
  }
}

async function renderStays() { const [rack, stays, tasks] = await Promise.all([api(`/room-rack?from=${today()}&days=1`), api('/stays'), api('/tasks')]); if (app.view !== 'stays') return; app.data.rack = rack; app.data.stays = stays; const cards = rack.rooms.map(room => { const stay = stays.find(item => item.room_id === room.id); const assignment = rack.assignments.find(item => item.room_id === room.id); const roomTasks = tasks.filter(item => item.room_id === room.id && item.status !== 'completed'); const guest = stay ? `${stay.first_name || ''} ${stay.last_name || ''}`.trim() : assignment ? `${assignment.guest_name || assignment.reservation_number} · Rezervasyon` : 'Boş'; const detail = stay ? 'Konaklayan · folyo, minibar ve çıkış işlemleri' : assignment ? `${formatTurkishDate(assignment.start_date)} — ${formatTurkishDate(assignment.end_date)} · Rezervasyon detayını aç` : 'Atanmış rezervasyon yok'; const cardStatus = stay ? room.status : assignment ? 'confirmed' : room.status; return `<button class="pms-room-center-card ${escapeHtml(cardStatus)}" data-room-center="${room.id}" data-reservation="${escapeHtml(assignment?.reservation_id || '')}"><div><strong>Oda ${escapeHtml(room.room_number)}</strong>${stay ? badge('checked_in') : assignment ? badge(assignment.reservation_status || 'confirmed') : badge(room.status)}</div><span>${escapeHtml(guest)}</span><small>${escapeHtml(detail)}</small><small>${roomTasks.length ? `${roomTasks.length} açık oda görevi` : 'Açık oda görevi yok'}</small></button>`; }).join(''); content.innerHTML = `<div class="pms-section-tools"><div><strong>Oda Operasyon Merkezi</strong><div class="pms-muted">Bugünün konaklayanları ve oda planındaki rezerve misafirler aynı odalarda görünür. Odaya basarak ilgili operasyon veya rezervasyon detayını açın.</div></div><button id="refresh-stays" class="btn btn-secondary">Yenile</button></div><div class="pms-room-center-grid">${cards}</div>`; document.getElementById('refresh-stays').addEventListener('click', () => showView('stays')); content.querySelectorAll('[data-room-center]').forEach(button => button.addEventListener('click', () => { const room = rack.rooms.find(item => item.id === button.dataset.roomCenter); const stay = stays.find(item => item.room_id === button.dataset.roomCenter); const roomTasks = tasks.filter(item => item.room_id === button.dataset.roomCenter && item.status !== 'completed'); if (stay) openRoomCenter(room, stay, roomTasks); else if (button.dataset.reservation) openReservation(button.dataset.reservation); else openRoomCenter(room, null, roomTasks); })); }

async function openRoomCenter(room, stay, tasks) { const folio = stay ? await api(`/folios/${stay.folio_id}`).catch(() => null) : null; const reversedTransactionIds = new Set((folio?.transactions || []).filter(item => item.transaction_type === 'reversal' && String(item.related_reference || '').startsWith('reversal:')).map(item => String(item.related_reference).slice('reversal:'.length))); const minibar = (folio?.transactions || []).filter(item => item.transaction_type === 'minibar' && !reversedTransactionIds.has(item.id)).reduce((sum, item) => sum + Number(item.debit || 0), 0); const guest = stay ? `${stay.first_name || ''} ${stay.last_name || ''}`.trim() : 'Konaklayan yok'; const taskText = tasks.length ? tasks.map(item => `${item.task_type}: ${item.details || 'Detay yok'}`).join(' · ') : 'Açık görev yok'; openModal(`Oda ${room.room_number} Operasyon Bilgisi`, `<div class="pms-list"><div class="pms-list-item"><span>Durum</span><strong>${badge(room.status)}</strong></div><div class="pms-list-item"><span>Konaklayan</span><strong>${escapeHtml(guest)}</strong></div><div class="pms-list-item"><span>Ayrılış</span><strong>${escapeHtml(stay?.business_date || room.departure_date || '-')}</strong></div><div class="pms-list-item"><span>Minibar</span><strong>${stay ? money(minibar) : 'Konaklama yok'}</strong></div><div class="pms-list-item"><span>Temizlik / Oda Görevi</span><strong>${escapeHtml(taskText)}</strong></div><div class="pms-list-item"><span>Klima</span><strong>${escapeHtml(label(room.ac_status || 'working'))}</strong></div><div class="pms-list-item"><span>Teknik Not</span><strong>${escapeHtml(room.maintenance_notes || 'Teknik not yok')}</strong></div><div class="pms-list-item"><span>Rahatsız Etmeyin</span><strong>${Number(room.dnd_active) ? 'Aktif' : 'Yok'}</strong></div></div><div class="pms-actions"><button id="room-center-edit" class="btn btn-secondary">Oda Bilgilerini Düzenle</button>${stay ? '<button id="room-center-folio" class="btn btn-primary">Folyo Aç</button><button id="room-center-receipt" class="btn btn-secondary">Hesap Fişi</button><button id="room-center-minibar" class="btn btn-secondary">Minibar Ekle</button><button id="room-center-move" class="btn btn-secondary">Oda Değiştir</button><button id="room-center-checkout" class="btn btn-success">Çıkış Yap</button>' : ''}</div>`); document.getElementById('room-center-edit').addEventListener('click', () => openRoomOperationsForm(room, stay)); document.getElementById('room-center-folio')?.addEventListener('click', () => { app.selectedFolio = stay.folio_id; closeModal(); showView('folios'); }); document.getElementById('room-center-receipt')?.addEventListener('click', () => openCheckoutReceipt(stay)); document.getElementById('room-center-minibar')?.addEventListener('click', () => openMinibarOptions(stay.folio_id)); document.getElementById('room-center-move')?.addEventListener('click', () => openMove(stay)); document.getElementById('room-center-checkout')?.addEventListener('click', () => checkout(stay)); }

function openRoomOperationsForm(room, stay) { const fields = [field('Klima', 'ac_status', 'text', room.ac_status || 'working', [{ value: 'working', label: 'Çalışıyor' }, { value: 'off', label: 'Kapalı' }, { value: 'fault', label: 'Arızalı' }]), field('Rahatsız Etmeyin', 'dnd_active', 'text', Number(room.dnd_active) ? '1' : '0', [{ value: '0', label: 'Yok' }, { value: '1', label: 'Aktif' }]), field('Teknik / Operasyon Notu', 'maintenance_notes', 'textarea', room.maintenance_notes || '', null, true)]; if (!stay) fields.unshift(field('Oda Durumu', 'status', 'text', room.status, [{ value: 'clean_vacant', label: 'Temiz Boş' }, { value: 'dirty_vacant', label: 'Kirli Boş' }, { value: 'maintenance', label: 'Bakımda' }, { value: 'out_of_order', label: 'Kullanıma Kapalı' }, { value: 'blocked', label: 'Bloke' }])); openModal(`Oda ${room.room_number} Bilgilerini Düzenle`, formLayout(fields, 'Kaydet')); const form = document.querySelector('[data-form]'); form.addEventListener('submit', async event => { event.preventDefault(); const data = formData(form); data.dnd_active = data.dnd_active === '1'; try { await api(`/rooms/${room.id}/operations`, { method: 'PATCH', body: JSON.stringify(data) }); closeModal(); message('Oda operasyon bilgileri kaydedildi.', 'success'); showView('stays'); } catch (error) { message(error.message); } }); document.querySelector('[data-close]').addEventListener('click', closeModal); }

function openStay(stay) { app.selectedStay = stay; app.selectedFolio = stay.folio_id; openModal(`Konaklama — ${stay.room_number}`, `<div class="pms-list"><div class="pms-list-item"><span>Misafir</span><strong>${escapeHtml(`${stay.first_name || ''} ${stay.last_name || ''}`)}</strong></div><div class="pms-list-item"><span>Folyo Bakiyesi</span><strong>${money(stay.balance)}</strong></div></div><div class="pms-actions"><button id="stay-folio" class="btn btn-primary">Folyo Aç</button><button id="stay-move" class="btn btn-secondary">Oda Değiştir</button><button id="stay-checkout" class="btn btn-success">Çıkış Yap</button></div>`); document.getElementById('stay-folio').addEventListener('click', () => { closeModal(); showView('folios'); }); document.getElementById('stay-move').addEventListener('click', () => openMove(stay)); document.getElementById('stay-checkout').addEventListener('click', () => checkout(stay)); }

async function openMove(stay) { const rack = app.data.rack || await api(`/room-rack?from=${today()}&days=1`); const rooms = rack.rooms.filter(room => room.status === 'clean_vacant'); openModal('Oda Değiştir', formLayout([field('Yeni Temiz Oda', 'room_id', 'text', '', rooms.map(room => ({ value: room.id, label: room.room_number }))), field('Yetkili Gerekçe', 'reason', 'textarea', '', null, true)], 'Oda Değiştir')); const form = document.querySelector('[data-form]'); form.addEventListener('submit', async event => { event.preventDefault(); try { await api(`/stays/${stay.id}/move`, { method: 'POST', body: JSON.stringify(formData(form)) }); closeModal(); message('Oda değişimi ve housekeeping handoff kaydedildi.', 'success'); showView('stays'); } catch (error) { message(error.message); } }); document.querySelector('[data-close]').addEventListener('click', closeModal); }
function receiptRows(items, amountKey) { return items.map(item => `<tr><td>${escapeHtml(label(item.transaction_type))}</td><td>${escapeHtml(item.description || label(item.payment_method))}</td><td>${escapeHtml(String(item.quantity || 1))}</td><td>${money(item[amountKey])}</td></tr>`).join('') || '<tr><td colspan="4" class="pms-muted">Kayıt bulunmuyor.</td></tr>'; }
function receiptMarkup(receipt) { const guest = `${receipt.stay.first_name || ''} ${receipt.stay.last_name || ''}`.trim() || 'Misafir'; return `<div class="pms-list"><div class="pms-list-item"><span>Misafir</span><strong>${escapeHtml(guest)}</strong></div><div class="pms-list-item"><span>Oda / Rezervasyon</span><strong>${escapeHtml(receipt.stay.room_number)} · ${escapeHtml(receipt.stay.reservation_number || '-')}</strong></div><div class="pms-list-item"><span>Konaklama</span><strong>${escapeHtml(receipt.stay.arrival_date || '-')} — ${escapeHtml(receipt.stay.departure_date || '-')}</strong></div></div><article class="pms-card"><h2>Ekstralar ve Konaklama Kalemleri</h2>${table(['Tür', 'Açıklama', 'Adet', 'Tutar'], receiptRows(receipt.charges, 'debit'))}</article><article class="pms-card"><h2>Tahsilatlar</h2>${table(['Yöntem', 'Açıklama', 'Adet', 'Tutar'], receiptRows(receipt.payments, 'credit'))}</article><div class="pms-list"><div class="pms-list-item"><span>Toplam Borç</span><strong>${money(receipt.total_charges)}</strong></div><div class="pms-list-item"><span>Toplam Tahsilat</span><strong>${money(receipt.total_payments)}</strong></div><div class="pms-list-item"><span>Kalan Bakiye</span><strong>${money(receipt.balance)}</strong></div></div>`; }
async function openCheckoutReceipt(stay, completedReceipt = null) { try { const receipt = completedReceipt || await api(`/stays/${stay.id}/checkout-receipt`); openModal('Konaklama Hesap Fişi', `${receiptMarkup(receipt)}<p class="pms-muted">Bu belge hesap fişidir; resmi e-Fatura veya e-Arşiv yerine geçmez.</p><div class="pms-actions"><button id="checkout-receipt-print" class="btn btn-primary">Yazdır / PDF</button><button data-close class="btn btn-secondary">Kapat</button></div>`); document.getElementById('checkout-receipt-print').addEventListener('click', () => printCheckoutReceipt(receipt)); document.querySelector('[data-close]').addEventListener('click', closeModal); } catch (error) { message(error.message); } }
function printCheckoutReceipt(receipt) { const output = window.open('', '_blank'); if (!output) return message('Tarayıcı yazdırma penceresini engelledi. Açılır pencere izni verip tekrar deneyin.'); const guest = `${receipt.stay.first_name || ''} ${receipt.stay.last_name || ''}`.trim() || 'Misafir'; const rows = (items, amountKey) => items.map(item => `<tr><td>${escapeHtml(label(item.transaction_type))}</td><td>${escapeHtml(item.description || label(item.payment_method))}</td><td>${escapeHtml(String(item.quantity || 1))}</td><td>${money(item[amountKey])}</td></tr>`).join(''); output.document.write(`<!doctype html><html lang="tr"><head><meta charset="utf-8"><title>Konaklama Hesap Fişi</title><style>body{font-family:Arial,sans-serif;color:#14212b;margin:32px}h1{margin:0 0 8px}p{margin:4px 0}table{border-collapse:collapse;width:100%;margin:18px 0}th,td{border:1px solid #d6dce0;padding:8px;text-align:left}th{background:#eef4f6}.total{font-size:18px;font-weight:700;text-align:right}.note{font-size:12px;color:#52616b}</style></head><body><h1>Aeon Boutique Hotel</h1><h2>Konaklama Hesap Fişi</h2><p><strong>Misafir:</strong> ${escapeHtml(guest)}</p><p><strong>Oda:</strong> ${escapeHtml(receipt.stay.room_number)} · <strong>Rezervasyon:</strong> ${escapeHtml(receipt.stay.reservation_number || '-')}</p><p><strong>Konaklama:</strong> ${escapeHtml(receipt.stay.arrival_date || '-')} — ${escapeHtml(receipt.stay.departure_date || '-')}</p><h3>Ekstralar ve Konaklama Kalemleri</h3><table><thead><tr><th>Tür</th><th>Açıklama</th><th>Adet</th><th>Tutar</th></tr></thead><tbody>${rows(receipt.charges, 'debit') || '<tr><td colspan="4">Kayıt bulunmuyor.</td></tr>'}</tbody></table><h3>Tahsilatlar</h3><table><thead><tr><th>Yöntem</th><th>Açıklama</th><th>Adet</th><th>Tutar</th></tr></thead><tbody>${rows(receipt.payments, 'credit') || '<tr><td colspan="4">Kayıt bulunmuyor.</td></tr>'}</tbody></table><p class="total">Toplam Borç: ${money(receipt.total_charges)}</p><p class="total">Toplam Tahsilat: ${money(receipt.total_payments)}</p><p class="total">Kalan Bakiye: ${money(receipt.balance)}</p><p class="note">Bu belge hesap fişidir; resmi e-Fatura veya e-Arşiv yerine geçmez.</p></body></html>`); output.document.close(); output.onload = () => { output.focus(); output.print(); }; }
async function checkout(stay) { try { const receipt = await api(`/stays/${stay.id}/checkout-receipt`); const paymentActions = Number(receipt.balance) > 0 ? `<div class="pms-actions"><button id="checkout-payment" class="btn btn-primary">Tahsilat Gir</button><button id="checkout-settle-full" class="btn btn-success">Kalanın Tamamını Tahsil Et</button></div>` : ''; openModal('Kontrollü Çıkış', `${receiptMarkup(receipt)}${paymentActions}${formLayout([field('Alacak / şirket hesabı gerekçesi', 'receivable_reason', 'textarea', '', null, true)], 'Çıkışı Tamamla')}`); const form = document.getElementById('pms-modal-body').querySelector('[data-form]'); form.addEventListener('submit', async event => { event.preventDefault(); try { const result = await api(`/stays/${stay.id}/checkout`, { method: 'POST', body: JSON.stringify(formData(form)) }); message('Çıkış, KBS çıkış kaydı ve kat hizmetleri görevi oluşturuldu. Hesap fişi hazır.', 'success'); openCheckoutReceipt(stay, result.receipt); showView('stays'); } catch (error) { message(error.message); } }); document.getElementById('checkout-payment')?.addEventListener('click', () => openCheckoutPayment(stay, receipt.balance)); document.getElementById('checkout-settle-full')?.addEventListener('click', () => openCheckoutPayment(stay, receipt.balance, true)); document.getElementById('pms-modal-body').querySelector('[data-close]').addEventListener('click', closeModal); } catch (error) { message(error.message); } }
function openCheckoutPayment(stay, balance, fillAmount = false) { const outstanding = Math.max(0, Number(balance || 0)); openModal('Çıkış Öncesi Tahsilat', `<div class="pms-list"><div class="pms-list-item"><span>Kalan Bakiye</span><strong>${money(outstanding)}</strong></div></div><div class="pms-actions"><button id="checkout-payment-full" class="btn btn-secondary" type="button">Tüm Tutarı Yaz</button></div>${formLayout([field('Tutar', 'amount', 'number', fillAmount ? outstanding.toFixed(2) : ''), field('Ödeme Yöntemi', 'payment_method', 'text', 'cash', [{ value: 'cash', label: 'Nakit' }, { value: 'credit_card', label: 'Kredi Kartı' }, { value: 'bank_transfer', label: 'Banka Havalesi' }]), field('Referans / POS No', 'reference')], 'Tahsilatı Kaydet')}`); const modalBody = document.getElementById('pms-modal-body'); const form = modalBody.querySelector('[data-form]'); modalBody.querySelector('#checkout-payment-full').addEventListener('click', () => { form.elements.amount.value = outstanding.toFixed(2); form.elements.amount.focus(); }); form.addEventListener('submit', async event => { event.preventDefault(); const data = formData(form); data.amount = Number(data.amount); try { await api(`/folios/${stay.folio_id}/payments`, { method: 'POST', body: JSON.stringify(data) }); message('Tahsilat kaydedildi. Çıkış özeti güncellendi.', 'success'); await checkout(stay); } catch (error) { message(error.message); } }); modalBody.querySelector('[data-close]').addEventListener('click', () => checkout(stay)); }

async function renderFolios() {
  const stays = await api('/stays'); if (app.view !== 'folios') return;
  if (!app.selectedFolio && stays[0]) app.selectedFolio = stays[0].folio_id;
  if (!app.selectedFolio) { content.innerHTML = '<div class="pms-empty">Açık folyo bulunmuyor.</div>'; return; }
  const folio = await api(`/folios/${app.selectedFolio}`); if (app.view !== 'folios') return;
  const selectedStay = stays.find(item => item.folio_id === app.selectedFolio);
  const reversedTransactionIds = new Set(folio.transactions.filter(item => item.transaction_type === 'reversal' && String(item.related_reference || '').startsWith('reversal:')).map(item => String(item.related_reference).slice('reversal:'.length)));
  const transactionRows = folio.transactions.map(item => {
    const description = item.transaction_type === 'payment' ? `Ödeme: ${label(item.payment_method)}` : item.description;
    const isReversal = item.transaction_type === 'reversal';
    const isReversed = reversedTransactionIds.has(item.id);
    return `<tr><td>${String(item.occurred_at).replace('T', ' ').slice(0, 16)}</td><td>${escapeHtml(label(item.transaction_type))}</td><td>${escapeHtml(description)}</td><td>${money(item.debit)}</td><td>${money(item.credit)}</td><td>${escapeHtml(label(item.payment_method || '-'))}</td><td>${isReversal ? '-' : isReversed ? 'İptal Edildi' : `<button class="btn btn-danger" data-reverse-folio="${item.id}">İptal Et</button>`}</td></tr>`;
  }).join('');
  content.innerHTML = `<section class="pms-folio-picker"><div class="pms-section-title"><h2>Aktif Folyolar</h2><p>Misafirin kutucuğuna basarak folyosunu açın.</p></div><div class="pms-grid">${stays.map(stay => `<button class="pms-kpi ${stay.folio_id === app.selectedFolio ? 'active' : ''}" data-folio="${stay.folio_id}" style="text-align:left;border-color:${stay.folio_id === app.selectedFolio ? '#0d9abb' : ''};background:${stay.folio_id === app.selectedFolio ? '#eaf8fc' : ''}"><strong style="font-size:17px">${escapeHtml(`${stay.first_name || ''} ${stay.last_name || ''}`.trim() || 'İsimsiz Misafir')}</strong><span>Oda ${escapeHtml(stay.room_number)}</span><span style="font-weight:800;color:#057a9e">Folyo ${money(stay.balance)}</span></button>`).join('')}</div></section><div class="pms-section-tools"><div><strong>${escapeHtml(`${selectedStay?.first_name || ''} ${selectedStay?.last_name || ''}`.trim() || 'Misafir Folyosu')}</strong><div class="pms-muted">Oda ${escapeHtml(selectedStay?.room_number || '-')}</div></div><div class="pms-actions"><button id="add-charge" class="btn btn-secondary">Masraf Ekle</button><button id="add-payment" class="btn btn-primary">Tahsilat</button><button id="settle-full" class="btn btn-success" ${Number(folio.balance) > 0 ? '' : 'disabled'}>Tüm Tutarı Tahsil Et</button></div></div><article class="pms-card"><h2>Folyo Bakiyesi <span class="pms-amount">${money(folio.balance)}</span></h2>${table(['Tarih', 'Tür', 'Açıklama', 'Borç', 'Alacak', 'Yöntem', 'İşlem'], transactionRows)}</article>`;
  content.querySelectorAll('[data-folio]').forEach(button => button.addEventListener('click', () => { app.selectedFolio = button.dataset.folio; showView('folios'); }));
  content.querySelectorAll('[data-reverse-folio]').forEach(button => button.addEventListener('click', async () => { if (!window.confirm('Bu satır iptal edilsin mi? Tutar bakiyeden geri alınır.')) return; try { await api(`/folios/${folio.folio.id}/transactions/${button.dataset.reverseFolio}/reverse`, { method: 'POST' }); message('Folyo satırı iptal edildi.', 'success'); showView('folios'); } catch (error) { message(error.message); } }));
  document.getElementById('add-charge').addEventListener('click', () => openCharge(folio.folio.id)); document.getElementById('add-payment').addEventListener('click', () => openPayment(folio.folio.id, folio.balance)); document.getElementById('settle-full').addEventListener('click', () => openPayment(folio.folio.id, folio.balance, true));
}
function openCharge(folioId) { const categories = [{ type: 'minibar', label: 'Minibar', icon: 'fa-wine-glass' }, { type: 'laundry', label: 'Çamaşırhane', icon: 'fa-shirt' }, { type: 'transfer', label: 'Transfer', icon: 'fa-car' }, { type: 'charge', label: 'Diğer Masraf', icon: 'fa-receipt' }]; openModal('Folyo Masrafı', `<p class="pms-muted">Türü seçin; Minibar için ürün ve fiyat listesi doğrudan açılır.</p><div class="pms-grid">${categories.map(item => `<button class="pms-kpi" data-charge-type="${item.type}"><i class="fa-solid ${item.icon}"></i><strong style="font-size:16px">${item.label}</strong><span>Seç ve devam et</span></button>`).join('')}</div>`); document.querySelectorAll('[data-charge-type]').forEach(button => button.addEventListener('click', () => button.dataset.chargeType === 'minibar' ? openMinibarOptions(folioId) : openChargeForm(folioId, button.dataset.chargeType))); }
async function openMinibarOptions(folioId) { openModal('Minibar Ürünleri', '<div class="pms-empty">Ürünler yükleniyor…</div>'); try { const response = await fetch(`/api/catalog?tenant_id=${encodeURIComponent(state.currentTenant)}`); if (!response.ok) throw new Error('Ürün listesi alınamadı.'); const items = (await response.json()).filter(item => item.category === 'minibar'); document.getElementById('pms-modal-body').innerHTML = items.length ? `<p class="pms-muted">Ürünü seçin, adet ve toplam tutarı onaylayın.</p><div class="pms-grid">${items.map(item => `<button class="pms-kpi" data-minibar-item="${escapeHtml(item.id)}"><strong style="font-size:16px">${escapeHtml(item.name)}</strong><span>Minibar</span><strong>${money(item.price)}</strong></button>`).join('')}</div><div class="pms-actions"><button id="minibar-back" class="btn btn-secondary">Masraf Türlerine Dön</button></div>` : '<div class="pms-empty">Minibar ürünü tanımlı değil.</div>'; document.querySelectorAll('[data-minibar-item]').forEach(button => button.addEventListener('click', () => { const item = items.find(entry => entry.id === button.dataset.minibarItem); if (item) confirmMinibarCharge(folioId, item); })); document.getElementById('minibar-back')?.addEventListener('click', () => openCharge(folioId)); } catch (error) { document.getElementById('pms-modal-body').innerHTML = `<div class="pms-empty pms-danger">${escapeHtml(error.message)}</div>`; } }
function confirmMinibarCharge(folioId, item) { openModal('Minibar Masrafını Onayla', `<div class="pms-list"><div class="pms-list-item"><span>Ürün</span><strong>${escapeHtml(item.name)}</strong></div><div class="pms-list-item"><span>Birim Fiyat</span><strong>${money(item.price)}</strong></div></div>${formLayout([field('Adet', 'quantity', 'number', 1)], 'Folyoya Ekle')}`); const modalBody = document.getElementById('pms-modal-body'); const form = modalBody.querySelector('[data-form]'); form.addEventListener('submit', async event => { event.preventDefault(); const quantity = Number(formData(form).quantity); if (!Number.isInteger(quantity) || quantity < 1) return message('Adet en az 1 olmalıdır.'); const submit = form.querySelector('button[type="submit"]'); submit.disabled = true; submit.textContent = 'Ekleniyor…'; try { await api(`/folios/${folioId}/transactions`, { method: 'POST', body: JSON.stringify({ transaction_type: 'minibar', description: item.name, amount: Number(item.price), quantity, department: 'Resepsiyon', related_reference: `minibar:${item.id}` }) }); closeModal(); message(`${quantity} adet ${item.name} folyo hesabına eklendi.`, 'success'); await showView('folios'); } catch (error) { submit.disabled = false; submit.textContent = 'Folyoya Ekle'; message(error.message); } }); modalBody.querySelector('[data-close]').addEventListener('click', () => openMinibarOptions(folioId)); }
function openChargeForm(folioId, type) { const labelsByType = { minibar: 'Minibar', laundry: 'Çamaşırhane', transfer: 'Transfer', charge: 'Diğer Masraf' }; openModal(`${labelsByType[type]} Masrafı`, formLayout([field('Açıklama', 'description'), field('Tutar', 'amount', 'number'), field('Departman', 'department', 'text', 'Resepsiyon'), field('Tür', 'transaction_type', 'text', type, [{ value: type, label: labelsByType[type] }])], 'Masrafı Kaydet')); const form = document.querySelector('[data-form]'); form.addEventListener('submit', async event => { event.preventDefault(); const data = formData(form); data.amount = Number(data.amount); try { await api(`/folios/${folioId}/transactions`, { method: 'POST', body: JSON.stringify(data) }); closeModal(); message('Folyo masrafı kaydedildi.', 'success'); showView('folios'); } catch (error) { message(error.message); } }); document.querySelector('[data-close]').addEventListener('click', closeModal); }
function openPayment(folioId, balance, fillAmount = false) { const outstanding = Math.max(0, Number(balance || 0)); openModal('Tahsilat', `<div class="pms-list"><div class="pms-list-item"><span>Açık Bakiye</span><strong>${money(outstanding)}</strong></div></div><div class="pms-actions"><button id="payment-full" class="btn btn-secondary" type="button">Tüm Tutarı Yaz</button></div>${formLayout([field('Tutar', 'amount', 'number', fillAmount ? outstanding.toFixed(2) : ''), field('Ödeme Yöntemi', 'payment_method', 'text', 'cash', [{ value: 'cash', label: 'Nakit' }, { value: 'credit_card', label: 'Kredi Kartı' }, { value: 'bank_transfer', label: 'Banka Havalesi' }]), field('Referans', 'reference')], 'Tahsilatı Kaydet')}`); const form = document.querySelector('[data-form]'); document.getElementById('payment-full').addEventListener('click', () => { form.elements.amount.value = outstanding.toFixed(2); form.elements.amount.focus(); }); form.addEventListener('submit', async event => { event.preventDefault(); const data = formData(form); data.amount = Number(data.amount); try { await api(`/folios/${folioId}/payments`, { method: 'POST', body: JSON.stringify(data) }); closeModal(); message('Tahsilat ve değiştirilemez hesap satırı kaydedildi.', 'success'); showView('folios'); } catch (error) { message(error.message); } }); document.querySelector('[data-close]').addEventListener('click', closeModal); }

async function renderInvoices() {
  const [invoices, candidates] = await Promise.all([api('/invoices'), api('/invoices/candidates')]);
  app.data.invoiceCandidates = candidates;
  content.innerHTML = `<div class="pms-section-tools"><div><strong>Fatura ve Tahsilat Belgesi</strong><div class="pms-muted">GİB/e-Arşiv entegratörü bağlanana kadar bu ekran resmi e-Fatura gönderimi yapmaz.</div></div><button id="invoice-create" class="btn btn-primary">Fatura Kes</button></div>${table(['Fatura No', 'Misafir / Ünvan', 'Rezervasyon', 'Tarih', 'Toplam', 'Durum', 'İşlem'], invoices.map(invoice => `<tr><td>${escapeHtml(invoice.invoice_number)}</td><td>${escapeHtml(invoice.customer_name)}</td><td>${escapeHtml(invoice.reservation_number || '-')}</td><td>${escapeHtml(invoice.issue_date)}</td><td>${money(invoice.total_amount)}</td><td>${badge(invoice.status)}</td><td><button class="btn btn-secondary" data-invoice="${invoice.id}">Görüntüle</button></td></tr>`).join('') || '<tr><td colspan="7" class="pms-muted">Henüz fatura kesilmedi.</td></tr>')}`;
  document.getElementById('invoice-create').addEventListener('click', openInvoiceForm);
  content.querySelectorAll('[data-invoice]').forEach(button => button.addEventListener('click', () => openInvoice(button.dataset.invoice)));
}

function openInvoiceForm() {
  const candidates = app.data.invoiceCandidates || [];
  if (!candidates.length) return message('Faturalandırılacak folyo kalemi bulunmuyor. Önce folyo masrafı kaydedin.');
  const first = candidates[0];
  const customerName = `${first.first_name || ''} ${first.last_name || ''}`.trim() || first.reservation_number || 'Misafir';
  openModal('Fatura Kes', formLayout([field('Folyo', 'folio_id', 'text', first.id, candidates.map(item => ({ value: item.id, label: `${item.reservation_number || item.details || item.id} · ${money(item.total_amount)}` })), true), field('Fatura Ünvanı / Misafir', 'customer_name', 'text', customerName, null, true), field('Vergi No / T.C. No', 'customer_tax_number'), field('Vergi Dairesi', 'customer_tax_office'), field('Fatura E-postası', 'customer_email', 'email'), field('Fatura Adresi', 'customer_address', 'textarea', '', null, true), field('KDV Oranı %', 'tax_rate', 'number', 20), field('Ödeme Yöntemi', 'payment_method', 'text', first.payment_method || 'credit_card', [{ value: 'cash', label: 'Nakit' }, { value: 'credit_card', label: 'Kredi Kartı' }, { value: 'bank_transfer', label: 'Banka Havalesi' }, { value: 'online_link', label: 'Ödeme Linki' }, { value: 'agency', label: 'Acenta' }, { value: 'company_receivable', label: 'Şirket Cari Hesabı' }]), field('Not', 'notes', 'textarea', '', null, true)], 'Faturayı Oluştur'));
  const form = document.querySelector('[data-form]');
  form.addEventListener('submit', async event => { event.preventDefault(); const data = formData(form); data.tax_rate = Number(data.tax_rate); try { const result = await api(`/folios/${data.folio_id}/invoices`, { method: 'POST', body: JSON.stringify(data) }); closeModal(); message(`${result.invoice_number} numaralı fatura oluşturuldu.`, 'success'); showView('invoices'); } catch (error) { message(error.message); } });
  document.querySelector('[data-close]').addEventListener('click', closeModal);
}

async function openInvoice(invoiceId) {
  try {
    const data = await api(`/invoices/${invoiceId}`);
    const invoice = data.invoice;
    openModal(`Fatura ${invoice.invoice_number}`, `<div class="pms-list"><div class="pms-list-item"><span>Fatura Ünvanı</span><strong>${escapeHtml(invoice.customer_name)}</strong></div><div class="pms-list-item"><span>Tarih / Durum</span><strong>${escapeHtml(invoice.issue_date)} · ${badge(invoice.status)}</strong></div><div class="pms-list-item"><span>Ara Toplam</span><strong>${money(invoice.subtotal)}</strong></div><div class="pms-list-item"><span>KDV</span><strong>${money(invoice.tax_amount)}</strong></div><div class="pms-list-item"><span>Genel Toplam</span><strong>${money(invoice.total_amount)}</strong></div></div>${table(['Açıklama', 'Tutar', 'KDV', 'Toplam'], data.items.map(item => `<tr><td>${escapeHtml(item.description)}</td><td>${money(item.unit_amount)}</td><td>${money(item.tax_amount)}</td><td>${money(item.total_amount)}</td></tr>`).join(''))}<div class="pms-actions"><button class="btn btn-primary" id="invoice-print">Yazdır / PDF</button>${invoice.status === 'issued' ? '<button class="btn btn-secondary" id="invoice-cancel">İptal Et</button>' : ''}</div>`);
    document.getElementById('invoice-print').addEventListener('click', () => printInvoice(data));
    document.getElementById('invoice-cancel')?.addEventListener('click', () => cancelInvoice(invoice.id));
  } catch (error) { message(error.message); }
}

async function printInvoice(data) {
  const invoice = data.invoice;
  let hotel = {};
  try {
    hotel = (await api('/hotel-profile')).hotel_profile || {};
  } catch (error) {
    console.error(error);
  }
  const output = window.open('', '_blank', 'noopener,noreferrer');
  if (!output) return message('Tarayıcı yeni pencereyi engelledi.');
  const hotelName = hotel.legal_name || hotel.hotel_name || 'Aeon Boutique Hotel';
  const hotelContact = [hotel.address, hotel.phone, hotel.email].filter(Boolean).map(escapeHtml).join('<br>');
  const hotelTax = [hotel.tax_office, hotel.tax_number ? `Vergi No: ${hotel.tax_number}` : ''].filter(Boolean).map(escapeHtml).join(' · ');
  output.document.write(`<!doctype html><html lang="tr"><head><meta charset="utf-8"><title>${escapeHtml(invoice.invoice_number)}</title><style>body{font:14px Arial;padding:36px;color:#17243a}h1{margin:0 0 6px}table{border-collapse:collapse;width:100%;margin-top:24px}th,td{border:1px solid #cbd5e1;padding:8px;text-align:left}.right{text-align:right}.total{font-size:18px;font-weight:700;margin-top:18px}.muted{color:#475569}</style></head><body><h1>${escapeHtml(hotelName)}</h1>${hotelContact || hotelTax ? `<p class="muted">${hotelContact}${hotelContact && hotelTax ? '<br>' : ''}${hotelTax}</p>` : ''}<p>Fatura No: ${escapeHtml(invoice.invoice_number)}<br>Tarih: ${escapeHtml(invoice.issue_date)}<br>Fatura Ünvanı: ${escapeHtml(invoice.customer_name)}<br>Vergi No / T.C.: ${escapeHtml(invoice.customer_tax_number || '-')}</p><table><thead><tr><th>Açıklama</th><th class="right">Tutar</th><th class="right">KDV</th><th class="right">Toplam</th></tr></thead><tbody>${data.items.map(item => `<tr><td>${escapeHtml(item.description)}</td><td class="right">${money(item.unit_amount)}</td><td class="right">${money(item.tax_amount)}</td><td class="right">${money(item.total_amount)}</td></tr>`).join('')}</tbody></table><p class="total">Genel Toplam: ${money(invoice.total_amount)}</p><p>Bu belge, GİB/e-Arşiv entegratörü yapılandırılmadıkça elektronik fatura yerine geçmez.</p></body></html>`);
  output.document.close();
  output.focus();
  output.print();
}

async function cancelInvoice(invoiceId) {
  const reason = window.prompt('İptal gerekçesini yazın:');
  if (!reason) return;
  try { await api(`/invoices/${invoiceId}/cancel`, { method: 'POST', body: JSON.stringify({ reason }) }); closeModal(); message('Fatura iptal kaydı oluşturuldu.', 'success'); showView('invoices'); } catch (error) { message(error.message); }
}

async function renderGuests(search = '') { const guests = await api(`/guests?search=${encodeURIComponent(search)}`); content.innerHTML = `<div class="pms-section-tools"><input id="guest-search" placeholder="Misafir, telefon, kimlik ara" value="${escapeHtml(search)}"><button id="guest-new" class="btn btn-primary">Yeni Misafir</button></div>${table(['Misafir', 'Telefon', 'Uyruk', 'Kimlik', 'VIP', 'Güncelleme'], guests.map(guest => `<tr><td>${escapeHtml(`${guest.first_name} ${guest.last_name}`)}</td><td>${escapeHtml(guest.phone || '-')}</td><td>${escapeHtml(guest.nationality || '-')}</td><td>${escapeHtml(guest.identity_number || guest.passport_number || '-')}</td><td>${guest.vip ? 'VIP' : '-'}</td><td>${String(guest.updated_at || '').slice(0, 10)}</td></tr>`).join(''))}`; document.getElementById('guest-search').addEventListener('change', event => renderGuests(event.target.value)); document.getElementById('guest-new').addEventListener('click', () => openReservationForm({})); }

async function renderTasks() { const tasks = await api('/tasks'); content.innerHTML = `<div class="pms-section-tools"><strong>Departman Görevleri</strong><button id="new-task" class="btn btn-primary">Görev Oluştur</button></div><div class="pms-list">${tasks.map(task => `<div class="pms-list-item"><div><strong>${escapeHtml(label(task.task_type))}</strong><div class="pms-muted">${escapeHtml(task.room_number || '-')} · ${escapeHtml(label(task.department))} · ${escapeHtml(task.details || '')}</div></div><div>${badge(task.status)} <button class="btn btn-secondary" data-complete-task="${task.id}">Tamamla</button></div></div>`).join('') || '<div class="pms-empty">Açık görev yok.</div>'}</div>`; document.getElementById('new-task').addEventListener('click', openTaskForm); content.querySelectorAll('[data-complete-task]').forEach(button => button.addEventListener('click', async () => { try { await api(`/tasks/${button.dataset.completeTask}`, { method: 'PATCH', body: JSON.stringify({ status: 'completed' }) }); showView('tasks'); } catch (error) { message(error.message); } })); }
function openTaskForm() { openModal('Görev Oluştur', formLayout([field('Tür', 'task_type', 'text', 'housekeeping', [{ value: 'housekeeping', label: 'Kat Hizmetleri' }, { value: 'maintenance', label: 'Teknik Servis' }, { value: 'wakeup', label: 'Uyandırma' }, { value: 'porter', label: 'Bagaj' }, { value: 'taxi', label: 'Taksi' }, { value: 'minibar', label: 'Minibar' }]), field('Departman', 'department', 'text', 'Housekeeping', [{ value: 'Housekeeping', label: 'Kat Hizmetleri' }, { value: 'Technical', label: 'Teknik Servis' }, { value: 'Kitchen', label: 'Mutfak' }, { value: 'Reception', label: 'Resepsiyon' }]), field('Oda Kimliği', 'room_id'), field('Öncelik', 'priority', 'text', 'normal', [{ value: 'low', label: 'Düşük' }, { value: 'normal', label: 'Normal' }, { value: 'high', label: 'Yüksek' }, { value: 'urgent', label: 'Acil' }]), field('Detay', 'details', 'textarea', '', null, true)], 'Görevi Gönder')); const form = document.querySelector('[data-form]'); form.addEventListener('submit', async event => { event.preventDefault(); const data = formData(form); try { if (data.department === 'Technical') { await submitMaintenanceWorkOrder(data); } else { await api('/tasks', { method: 'POST', body: JSON.stringify(data) }); } closeModal(); message('Görev ilgili departmana atandı.', 'success'); showView('tasks'); } catch (error) { message(error.message); } }); document.querySelector('[data-close]').addEventListener('click', closeModal); }

// The generic task board (`reception_tasks`) has no reader on the maintenance side —
// technical work only shows up in the Maintenance portal via `technical_work_orders`,
// so a "Technical" task must be filed there instead, not in `reception_tasks`.
async function submitMaintenanceWorkOrder(data) {
  const priorityMap = { low: 'normal', normal: 'normal', high: 'high', urgent: 'critical' };
  const response = await fetch(`/api/maintenance/work-orders?tenant_id=${encodeURIComponent(state.currentTenant)}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      roomId: data.room_id || null,
      category: 'general',
      priority: priorityMap[data.priority] || 'normal',
      summary: data.details || 'Resepsiyon üzerinden bildirilen arıza.'
    })
  });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body.error || 'İş emri oluşturulamadı.');
  return body;
}

async function renderKbs() { const records = await api('/kbs'); content.innerHTML = `<article class="pms-card"><h2>KBS Hazırlık ve Mutabakat Kuyruğu</h2><p class="pms-muted">Doğrudan elektronik gönderim resmi kurum kimlik bilgileri olmadan kapalıdır. Manuel süreçte resmi referansı kaydedin.</p>${table(['Tür', 'Misafir', 'Durum', 'Doğrulama', 'Tekrar', 'İşlem'], records.map(item => `<tr><td>${escapeHtml(item.notification_type)}</td><td>${escapeHtml(`${item.first_name} ${item.last_name}`)}</td><td>${badge(item.status)}</td><td>${escapeHtml(item.validation_status)}</td><td>${item.retry_count}</td><td><button class="btn btn-secondary" data-kbs="${item.id}">Manuel Kayıt</button></td></tr>`).join(''))}</article>`; content.querySelectorAll('[data-kbs]').forEach(button => button.addEventListener('click', () => openKbsUpdate(button.dataset.kbs))); }
function openKbsUpdate(id) { openModal('KBS Manuel Gönderim Kaydı', formLayout([field('Durum', 'status', 'text', 'manual_review', [{ value: 'pending', label: 'Bekliyor' }, { value: 'submitted', label: 'Gönderildi' }, { value: 'accepted', label: 'Kabul Edildi' }, { value: 'rejected', label: 'Reddedildi' }, { value: 'manual_review', label: 'Manuel İnceleme' }]), field('Resmi Referans', 'response_reference'), field('Hata / Açıklama', 'error_message', 'textarea', '', null, true)], 'Kaydı Güncelle')); const form = document.querySelector('[data-form]'); form.addEventListener('submit', async event => { event.preventDefault(); try { await api(`/kbs/${id}`, { method: 'PATCH', body: JSON.stringify(formData(form)) }); closeModal(); message('KBS mutabakat kaydı güncellendi.', 'success'); showView('kbs'); } catch (error) { message(error.message); } }); document.querySelector('[data-close]').addEventListener('click', closeModal); }

async function renderShifts() { const audits = await api(`/reports?from=${today()}&to=${today()}`); content.innerHTML = `<div class="pms-grid"><article class="pms-kpi"><strong>${money(audits.summary.payments)}</strong><span>Bugün Tahsilat</span></article><article class="pms-kpi"><strong>${money(audits.summary.revenue)}</strong><span>Rezervasyon Geliri</span></article></div><article class="pms-card"><h2>Vardiya ve Gece Operasyonu</h2><div class="pms-actions"><button id="shift-open" class="btn btn-primary">Vardiya Aç</button><button id="night-audit" class="btn btn-secondary">Gece Denetimini Çalıştır</button></div></article>`; document.getElementById('shift-open').addEventListener('click', () => openShift()); document.getElementById('night-audit').addEventListener('click', async () => { try { const result = await api('/night-audit', { method: 'POST', body: JSON.stringify({ business_date: today() }) }); message(`Gece denetimi tamamlandı: ${result.summary.posted_accommodation} geceleme işlendi.`, 'success'); } catch (error) { message(error.message); } }); }
function openShift() { openModal('Vardiya Açılışı', formLayout([field('Açılış Kasası', 'opening_cash', 'number', 0), field('Devir Teslim Notu', 'handover_notes', 'textarea', '', null, true)], 'Vardiyayı Aç')); const form = document.querySelector('[data-form]'); form.addEventListener('submit', async event => { event.preventDefault(); const data = formData(form); data.opening_cash = Number(data.opening_cash); try { await api('/shifts/open', { method: 'POST', body: JSON.stringify(data) }); closeModal(); message('Vardiya açıldı.', 'success'); } catch (error) { message(error.message); } }); document.querySelector('[data-close]').addEventListener('click', closeModal); }

async function renderReports() { const from = today(); const report = await api(`/reports?from=${from}&to=${from}`); content.innerHTML = `<article class="pms-card"><h2>Resepsiyon Raporları — ${from}</h2><div class="pms-grid"><div class="pms-kpi"><strong>${report.summary.reservations}</strong><span>Rezervasyon</span></div><div class="pms-kpi"><strong>${money(report.summary.revenue)}</strong><span>Gelir</span></div><div class="pms-kpi"><strong>${money(report.summary.payments)}</strong><span>Tahsilat</span></div><div class="pms-kpi"><strong>${report.summary.occupancy_rooms}</strong><span>Dolu Oda</span></div></div><div class="pms-actions"><button id="print-report" class="btn btn-secondary">Yazdır / PDF</button><button id="export-report" class="btn btn-primary">CSV Dışa Aktar</button></div></article>`; document.getElementById('print-report').addEventListener('click', () => window.print()); document.getElementById('export-report').addEventListener('click', () => { const csv = ['type,count', `reservations,${report.summary.reservations}`, `revenue,${report.summary.revenue}`, `payments,${report.summary.payments}`, `occupied_rooms,${report.summary.occupancy_rooms}`].join('\n'); const objectUrl = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); const anchor = document.createElement('a'); anchor.href = objectUrl; anchor.download = `aeon-reception-${from}.csv`; anchor.style.display = 'none'; document.body.appendChild(anchor); anchor.click(); anchor.remove(); setTimeout(() => URL.revokeObjectURL(objectUrl), 1000); }); }

async function renderChannels() { content.innerHTML = `<iframe class="pms-channel-frame" title="HotelRunner Kanal Yönetimi" src="/channel-manager.html?tenant_id=${encodeURIComponent(state.currentTenant)}&embedded=1"></iframe>`; }

const renderers = { dashboard: renderDashboard, rack: renderRack, reservations: renderReservations, precheckins: renderPrecheckins, checkin: renderCheckin, stays: renderStays, folios: renderFolios, invoices: renderInvoices, tasks: renderTasks, kbs: renderKbs, shifts: renderShifts, reports: renderReports, channels: renderChannels };
async function showView(view) { const requestId = (app.viewRequestId || 0) + 1; app.viewRequestId = requestId; app.view = view; title.textContent = names[view]; document.querySelectorAll('#pms-nav button').forEach(button => button.classList.toggle('active', button.dataset.view === view)); content.innerHTML = '<div class="pms-empty">Yükleniyor…</div>'; try { await renderers[view](); } catch (error) { if (app.viewRequestId === requestId) content.innerHTML = `<div class="pms-empty pms-danger">${escapeHtml(error.message)}</div>`; } }

document.addEventListener('DOMContentLoaded', async () => { const user = await window.aeonBoot(); if (!user) return; const role = String(user.role || '').toLowerCase(); if (!['reception', 'admin', 'manager', 'yönetici'].includes(role)) { window.location.replace(`/login.html?tenant_id=${state.currentTenant}`); return; } document.querySelectorAll('#pms-nav button').forEach(button => button.addEventListener('click', () => showView(button.dataset.view))); document.getElementById('logout').addEventListener('click', () => window.aeonLogout()); document.getElementById('logout-topbar').addEventListener('click', () => window.aeonLogout()); document.getElementById('pms-modal-close').addEventListener('click', closeModal); document.getElementById('pms-modal').addEventListener('click', event => { if (event.target.id === 'pms-modal') closeModal(); }); document.getElementById('global-search').addEventListener('change', event => { showView('reservations'); setTimeout(() => renderReservations(event.target.value), 100); }); initReceptionSSE(); await showView('dashboard'); });
